{"new_str":"    """Encode a control PING frame using the active ZephyrWire framing standard.

    v3 frame, ``FRAME_TYPE_PING`` with ``FLAG_CONTROL``; payload is a
    big-endian u32 ``seq`` followed by an 8-byte nonce.
    """
    if isinstance(seq, bool) or not isinstance(seq, int) or not (0 <= seq <= U32_MAX):
        raise WireFormatError("seq out of u32 range")
    if not isinstance(nonce, (bytes, bytearray)) or len(nonce) != PING_NONCE_LEN:
        raise WireFormatError("nonce must be exactly 8 bytes")
    payload = seq.to_bytes(4, "big") + bytes(nonce)
    return encode_v3_frame(FRAME_TYPE_PING, FLAG_CONTROL, payload)


def decode_control_ping(raw: bytes) -> tuple[int, bytes]:
    """Decode and validate an active-standard control PING frame into ``(seq, nonce)``."""
    if not isinstance(raw, (bytes, bytearray)) or not raw:
        raise WireFormatError("empty or invalid wire buffer")
    if raw[0] != V3_MAGIC:
        raise WireFormatError(f"control ping must use v3 framing, got magic 0x{raw[0]:02x}")
    frame = decode_v3_frame(raw)
    if frame.frame_type != FRAME_TYPE_PING:
        raise WireFormatError("expected PING frame")
    if frame.flags != FLAG_CONTROL:
        raise WireFormatError("PING frame must carry exactly FLAG_CONTROL")
    if len(frame.payload) != PING_PAYLOAD_LEN:
        raise WireFormatError("ping payload must be 12 bytes")
    return int.from_bytes(frame.payload[:4], "big"), frame.payload[4:]","old_str":"    """Encode a control PING frame using the active ZephyrWire framing standard."""
